/// <summary>
/// Data contract class as a response for service <c>METPaymentStatusUpdateService</c>
/// </summary>
[DataContractAttribute]
class METPaymentStatusUpdateResponse extends METBaseResponseContract
{
}

Method.Source:
    /// <summary>
    /// Contruct a new Response contract
    /// </summary>
    /// <param name = "_result">Result of the cancellation</param>
    /// <param name = "_message">Message Result</param>
    /// <returns>new contract</returns>
    public static METPaymentStatusUpdateResponse newFromParameters(METProcessingStatus _result, Description255 _message)
    {
        METPaymentStatusUpdateResponse paymentStatusUpdateResponse = new METPaymentStatusUpdateResponse();

        paymentStatusUpdateResponse.parmResult(enum2Symbol(enumNum(METProcessingStatus), enum2int(_result)));
        paymentStatusUpdateResponse.parmMessage(_message);

        return paymentStatusUpdateResponse;
    }
